int absdiff_se(int x, int y) {
  if (x >= y) {
    ge_cnt++;
    return x - y;
  } else {
    lt_cnt++;
    return y - x;
  }
}

; Assembly code (simplified)
.globl absdiff_se
absdiff_se:
  cmpl %edi, %esi  ; Compare x and y
  jge .L8         ; Jump to line 8 if x >= y
  incl lt_cnt     ; Increment lt_cnt
  movl %esi, %eax ; move y to eax
  subl %edi, %eax ; eax = y - x
  ret              ; Return
.L8:
  incl ge_cnt     ; Increment ge_cnt
  movl %edi, %eax ; move x to eax
  subl %esi, %eax ; eax = x - y
  ret              ; Return
